    data = sys.stdin.buffer.read().split(b"\n")
    eps = {}
    skipped = 0
    for raw in data:
        if not raw.strip():
            continue
        try:
            o = json.loads(raw.decode("utf-8"))
        except (ValueError, RecursionError):
            skipped += 1
            continue
        if not isinstance(o, dict):
            skipped += 1
            continue
        e = o.get("endpoint")
        ms = o.get("ms")
        if isinstance(ms, float) and ms == ms and ms not in (float("inf"), float("-inf")) and ms == int(ms):
            ms = int(ms)
        if not isinstance(e, str) or isinstance(ms, bool) or not isinstance(ms, int) or ms < 0:
            skipped += 1
            continue
        eps.setdefault(e, []).append(ms)
    out = []
    for e in sorted(eps, key=lambda s: s.encode("utf-8", "surrogatepass")):
        v = sorted(eps[e])
        n = len(v)
        def p(P):
            return v[(P * n + 99) // 100 - 1]
        out.append("%s count=%d p50=%d p95=%d" % (e, n, p(50), p(95)))
    if skipped:
        out.append("skipped %d" % skipped)
    sys.stdout.buffer.write(("\n".join(out) + "\n" if out else "").encode("utf-8", "surrogatepass"))

